import os
import subprocess
from pathlib import Path
from urllib.parse import urlparse
import psycopg2
from fastapi import FastAPI, Depends, HTTPException, Header
from fastapi.responses import FileResponse
from fastapi.security import OAuth2PasswordRequestForm, OAuth2PasswordBearer
from decimal import Decimal, ROUND_HALF_UP
from sqlalchemy import inspect, text
from sqlalchemy.orm import Session
from fastapi.middleware.cors import CORSMiddleware
from datetime import date, datetime, timedelta, timezone
from .database import Base, engine, SessionLocal
from . import models, schemas
from .billing import ensure_default_tariffs, get_active_tariffs, build_quote
from .auth import verify_password, get_password_hash, create_access_token, decode_access_token

oauth2_scheme = OAuth2PasswordBearer(tokenUrl="login")

app = FastAPI()

DEFAULT_PLACE_PRICE_PER_NIGHT = Decimal("15.00")
BACKUP_DIR = Path(os.getenv("BACKUP_DIR", "/var/backups/campingplatz"))
BACKUP_RETENTION_DAYS = int(os.getenv("BACKUP_RETENTION_DAYS", "30"))
BACKUP_FILE_PREFIX = "camping_backup_"
BACKUP_FILE_SUFFIX = ".dump"
BACKUP_RESTORE_SAFETY_PREFIX = "pre_restore_backup_"
BACKUP_ALLOWED_PREFIXES = (BACKUP_FILE_PREFIX, BACKUP_RESTORE_SAFETY_PREFIX)


def quantize_money(value: Decimal) -> Decimal:
    return value.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)


def parse_vehicle_size_length(vehicle_size: str | None) -> float | None:
    if vehicle_size is None or vehicle_size.strip() == "":
        return None

    normalized = vehicle_size.lower().replace("m", "").replace(",", ".").strip()
    try:
        value = float(normalized)
    except ValueError:
        return None

    return value if value > 0 else None


def derive_people_count(adult_count: int, child_count: int) -> int:
    return max(0, adult_count) + max(0, child_count)


def normalize_optional_text(value: str | None) -> str | None:
    if value is None:
        return None

    normalized = value.strip()
    return normalized or None


def ensure_backup_dir_exists() -> None:
    BACKUP_DIR.mkdir(parents=True, exist_ok=True)


def parse_database_url_for_pg_dump(database_url: str) -> dict[str, str]:
    parsed = urlparse(database_url)
    if parsed.scheme not in {"postgresql", "postgres"}:
        raise HTTPException(status_code=500, detail="Backup unterstützt nur PostgreSQL")

    database_name = parsed.path.lstrip("/")
    if not database_name:
        raise HTTPException(status_code=500, detail="Ungültige DATABASE_URL für Backup")

    return {
        "host": parsed.hostname or "localhost",
        "port": str(parsed.port or 5432),
        "user": parsed.username or "",
        "password": parsed.password or "",
        "database": database_name,
    }


def build_backup_file_metadata(file_path: Path) -> dict:
    stat = file_path.stat()
    return {
        "file_name": file_path.name,
        "size_bytes": stat.st_size,
        "created_at": datetime.fromtimestamp(stat.st_mtime, tz=timezone.utc),
    }


def iter_backup_paths() -> list[Path]:
    ensure_backup_dir_exists()
    files: list[Path] = []
    for prefix in BACKUP_ALLOWED_PREFIXES:
        files.extend(
            path
            for path in BACKUP_DIR.glob(f"{prefix}*{BACKUP_FILE_SUFFIX}")
            if path.is_file()
        )
    files.sort(key=lambda p: p.stat().st_mtime, reverse=True)
    return files


def list_backup_files() -> list[dict]:
    return [build_backup_file_metadata(path) for path in iter_backup_paths()]


def remove_expired_backups() -> None:
    if BACKUP_RETENTION_DAYS <= 0:
        return

    cutoff = datetime.now(timezone.utc) - timedelta(days=BACKUP_RETENTION_DAYS)
    for path in iter_backup_paths():
        if not path.is_file():
            continue
        modified_at = datetime.fromtimestamp(path.stat().st_mtime, tz=timezone.utc)
        if modified_at < cutoff:
            path.unlink(missing_ok=True)


def create_database_backup(prefix: str = BACKUP_FILE_PREFIX) -> dict:
    ensure_backup_dir_exists()
    db_config = parse_database_url_for_pg_dump(
        os.getenv("DATABASE_URL", "postgresql://camping:camping@localhost:5432/camping")
    )

    timestamp = datetime.now(timezone.utc).strftime("%Y%m%d_%H%M%S")
    backup_file = BACKUP_DIR / f"{prefix}{timestamp}{BACKUP_FILE_SUFFIX}"

    cmd = [
        "pg_dump",
        "-h",
        db_config["host"],
        "-p",
        db_config["port"],
        "-U",
        db_config["user"],
        "-d",
        db_config["database"],
        "-F",
        "c",
        "-f",
        str(backup_file),
    ]

    env = os.environ.copy()
    if db_config["password"]:
        env["PGPASSWORD"] = db_config["password"]

    try:
        subprocess.run(cmd, env=env, check=True, capture_output=True, text=True)
    except FileNotFoundError as exc:
        raise HTTPException(status_code=500, detail="pg_dump ist auf dem Server nicht verfügbar") from exc
    except subprocess.CalledProcessError as exc:
        stderr = (exc.stderr or "").strip()
        raise HTTPException(status_code=500, detail=f"Backup fehlgeschlagen: {stderr or 'Unbekannter Fehler'}") from exc

    remove_expired_backups()
    return build_backup_file_metadata(backup_file)


def resolve_backup_file(file_name: str) -> Path:
    safe_name = Path(file_name).name
    if safe_name != file_name:
        raise HTTPException(status_code=400, detail="Ungültiger Dateiname")

    if not (safe_name.endswith(BACKUP_FILE_SUFFIX) and safe_name.startswith(BACKUP_ALLOWED_PREFIXES)):
        raise HTTPException(status_code=400, detail="Ungültiger Dateiname")

    target = BACKUP_DIR / safe_name
    if not target.exists() or not target.is_file():
        raise HTTPException(status_code=404, detail="Backup-Datei nicht gefunden")

    return target


def terminate_database_connections(db_config: dict[str, str]) -> None:
    maintenance_db = os.getenv("BACKUP_MAINTENANCE_DB", "postgres")
    try:
        with psycopg2.connect(
            host=db_config["host"],
            port=db_config["port"],
            user=db_config["user"],
            password=db_config["password"],
            dbname=maintenance_db,
        ) as conn:
            conn.autocommit = True
            with conn.cursor() as cur:
                cur.execute(
                    """
                    SELECT pg_terminate_backend(pid)
                    FROM pg_stat_activity
                    WHERE datname = %s
                      AND pid <> pg_backend_pid()
                    """,
                    (db_config["database"],),
                )
    except psycopg2.Error as exc:
        raise HTTPException(
            status_code=500,
            detail=f"Offene Datenbankverbindungen konnten nicht beendet werden: {str(exc).strip()}",
        ) from exc


def restore_database_backup(file_name: str) -> dict[str, str]:
    target_backup = resolve_backup_file(file_name)
    safety_backup = create_database_backup(prefix=BACKUP_RESTORE_SAFETY_PREFIX)
    db_config = parse_database_url_for_pg_dump(
        os.getenv("DATABASE_URL", "postgresql://camping:camping@localhost:5432/camping")
    )

    # Close SQLAlchemy pool connections before restore to avoid lock conflicts.
    engine.dispose()
    terminate_database_connections(db_config)

    restore_cmd = [
        "pg_restore",
        "-h",
        db_config["host"],
        "-p",
        db_config["port"],
        "-U",
        db_config["user"],
        "-d",
        db_config["database"],
        "--clean",
        "--if-exists",
        "--no-owner",
        "--no-privileges",
        str(target_backup),
    ]

    env = os.environ.copy()
    if db_config["password"]:
        env["PGPASSWORD"] = db_config["password"]

    def is_ignorable_transaction_timeout_warning(stderr_text: str) -> bool:
        normalized = (stderr_text or "").lower()
        if "unrecognized configuration parameter \"transaction_timeout\"" not in normalized:
            return False
        if "errors ignored on restore: 1" not in normalized:
            return False
        # Treat this as ignorable only when the sole failing query is the SET transaction_timeout.
        return normalized.count("could not execute query") == 1

    try:
        subprocess.run(restore_cmd, env=env, check=True, capture_output=True, text=True)
    except FileNotFoundError as exc:
        raise HTTPException(status_code=500, detail="pg_restore ist auf dem Server nicht verfügbar") from exc
    except subprocess.CalledProcessError as exc:
        stderr = (exc.stderr or "").strip()
        if is_ignorable_transaction_timeout_warning(stderr):
            return {
                "message": "Backup wurde wiederhergestellt (mit kompatibler Warnung zu transaction_timeout)",
                "restored_file": target_backup.name,
                "safety_backup_file": safety_backup["file_name"],
            }
        raise HTTPException(status_code=500, detail=f"Restore fehlgeschlagen: {stderr or 'Unbekannter Fehler'}") from exc
    finally:
        engine.dispose()

    return {
        "message": "Backup wurde erfolgreich wiederhergestellt",
        "restored_file": target_backup.name,
        "safety_backup_file": safety_backup["file_name"],
    }


def run_schema_migrations():
    inspector = inspect(engine)

    with engine.begin() as connection:
        if inspector.has_table("places"):
            place_columns = {column["name"] for column in inspector.get_columns("places")}

            if "price_per_night" not in place_columns:
                connection.execute(
                    text(
                        "ALTER TABLE places ADD COLUMN price_per_night NUMERIC(10,2) NOT NULL DEFAULT 15.00"
                    )
                )

        if inspector.has_table("bookings"):
            booking_columns = {column["name"] for column in inspector.get_columns("bookings")}

            if "booking_number" not in booking_columns:
                connection.execute(text("ALTER TABLE bookings ADD COLUMN booking_number VARCHAR"))

            if "guest_street" not in booking_columns:
                connection.execute(text("ALTER TABLE bookings ADD COLUMN guest_street VARCHAR"))

            if "guest_postal_code" not in booking_columns:
                connection.execute(text("ALTER TABLE bookings ADD COLUMN guest_postal_code VARCHAR"))

            if "guest_city" not in booking_columns:
                connection.execute(text("ALTER TABLE bookings ADD COLUMN guest_city VARCHAR"))

            # Falls keine echte Migrationslösung genutzt wird, muss folgendes SQL lokal und auf dem Server ausgeführt werden:
            # ALTER TABLE bookings ADD COLUMN IF NOT EXISTS nationality VARCHAR;
            if "nationality" not in booking_columns:
                connection.execute(text("ALTER TABLE bookings ADD COLUMN nationality VARCHAR"))

            if "people_count" not in booking_columns:
                connection.execute(
                    text(
                        "ALTER TABLE bookings ADD COLUMN people_count INTEGER NOT NULL DEFAULT 1"
                    )
                )

            if "has_electricity" not in booking_columns:
                connection.execute(
                    text(
                        "ALTER TABLE bookings ADD COLUMN has_electricity BOOLEAN NOT NULL DEFAULT FALSE"
                    )
                )

            if "dog_count" not in booking_columns:
                connection.execute(
                    text("ALTER TABLE bookings ADD COLUMN dog_count INTEGER NOT NULL DEFAULT 0")
                )

            if "place_price_per_night" not in booking_columns:
                connection.execute(
                    text(
                        "ALTER TABLE bookings ADD COLUMN place_price_per_night NUMERIC(10,2) NOT NULL DEFAULT 15.00"
                    )
                )

            if "adult_count" not in booking_columns:
                connection.execute(text("ALTER TABLE bookings ADD COLUMN adult_count INTEGER NOT NULL DEFAULT 1"))

            if "child_count" not in booking_columns:
                connection.execute(text("ALTER TABLE bookings ADD COLUMN child_count INTEGER NOT NULL DEFAULT 0"))

            if "day_visitor_count" not in booking_columns:
                connection.execute(text("ALTER TABLE bookings ADD COLUMN day_visitor_count INTEGER NOT NULL DEFAULT 0"))

            if "has_waste" not in booking_columns:
                connection.execute(text("ALTER TABLE bookings ADD COLUMN has_waste BOOLEAN NOT NULL DEFAULT FALSE"))

            if "has_rhine_view" not in booking_columns:
                connection.execute(text("ALTER TABLE bookings ADD COLUMN has_rhine_view BOOLEAN NOT NULL DEFAULT FALSE"))

            if "car_count" not in booking_columns:
                connection.execute(text("ALTER TABLE bookings ADD COLUMN car_count INTEGER NOT NULL DEFAULT 0"))

            if "motorcycle_count" not in booking_columns:
                connection.execute(text("ALTER TABLE bookings ADD COLUMN motorcycle_count INTEGER NOT NULL DEFAULT 0"))

            if "camper_count" not in booking_columns:
                connection.execute(text("ALTER TABLE bookings ADD COLUMN camper_count INTEGER NOT NULL DEFAULT 0"))

            if "camper_length_m" not in booking_columns:
                connection.execute(text("ALTER TABLE bookings ADD COLUMN camper_length_m FLOAT"))

            if "tent_tariff_code" not in booking_columns:
                connection.execute(text("ALTER TABLE bookings ADD COLUMN tent_tariff_code VARCHAR"))

            if "pricing_snapshot" not in booking_columns:
                connection.execute(text("ALTER TABLE bookings ADD COLUMN pricing_snapshot JSON"))

            if "billing_total" not in booking_columns:
                connection.execute(text("ALTER TABLE bookings ADD COLUMN billing_total NUMERIC(10,2)"))

            connection.execute(
                text(
                    """
                    UPDATE bookings b
                    SET place_price_per_night = COALESCE(p.price_per_night, 15.00)
                    FROM places p
                    WHERE b.place_id = p.id
                      AND (b.place_price_per_night IS NULL OR b.place_price_per_night < 0)
                    """
                )
            )

            connection.execute(
                text(
                    """
                    WITH numbered AS (
                        SELECT
                            id,
                            COALESCE(EXTRACT(YEAR FROM start_date)::int, EXTRACT(YEAR FROM CURRENT_DATE)::int) AS y,
                            ROW_NUMBER() OVER (
                                PARTITION BY COALESCE(EXTRACT(YEAR FROM start_date)::int, EXTRACT(YEAR FROM CURRENT_DATE)::int)
                                ORDER BY id
                            ) AS seq
                        FROM bookings
                    )
                    UPDATE bookings b
                    SET booking_number = CONCAT(numbered.y::text, '-', LPAD(numbered.seq::text, 5, '0'))
                    FROM numbered
                    WHERE b.id = numbered.id
                      AND (b.booking_number IS NULL OR b.booking_number = '')
                    """
                )
            )

            connection.execute(
                text(
                    "CREATE UNIQUE INDEX IF NOT EXISTS ix_bookings_booking_number ON bookings (booking_number)"
                )
            )

        if inspector.has_table("tariffs") is False:
            connection.execute(
                text(
                    """
                    CREATE TABLE tariffs (
                        id SERIAL PRIMARY KEY,
                        code VARCHAR NOT NULL UNIQUE,
                        label VARCHAR NOT NULL,
                        unit VARCHAR NOT NULL,
                        price NUMERIC(10,2) NOT NULL,
                        valid_from DATE NOT NULL,
                        valid_to DATE
                    )
                    """
                )
            )


def generate_booking_number(db: Session, year: int) -> str:
    prefix = f"{year}-"
    latest = (
        db.query(models.Booking)
        .filter(models.Booking.booking_number.like(f"{prefix}%"))
        .order_by(models.Booking.booking_number.desc())
        .first()
    )

    if latest and latest.booking_number:
        try:
            last_sequence = int(latest.booking_number.split("-")[1])
        except (IndexError, ValueError):
            last_sequence = 0
    else:
        last_sequence = 0

    return f"{year}-{str(last_sequence + 1).zfill(5)}"


def quote_from_booking_payload(
    booking_data: schemas.BookingCreate | schemas.BookingUpdate | schemas.BookingQuoteRequest,
    place: models.Place,
    db: Session,
):
    tariffs = get_active_tariffs(db, booking_data.start_date)
    if not tariffs:
        raise HTTPException(status_code=500, detail="Keine aktiven Tarife konfiguriert")
    return build_quote(booking_data, place, tariffs)

