    setError(null);
    setLoading(false);
    setHasLoadedOnce(false);
    setSelectedFocusDateIso(null);
    setSelectedFocusBookingId(null);
    setActionSuccess(null);
    setUserCreateSuccess(null);
    setUserCreateError(null);
  }

   async function loadUsers() {
     if (currentUser?.role !== "developer") return;

     try {
       setUsersError(null);
       const usersData = await fetchUsers();
       setUsers(usersData);
     } catch (err: any) {
       setUsersError(err.message || "Fehler beim Laden der Benutzer");
     }
   }

   useEffect(() => {
     if (currentUser?.role === "developer") {
       loadUsers();
     }
   }, [currentUser]);

   useEffect(() => {
     if (currentUser?.role === "developer" || currentUser?.role === "operator") {
       loadBackups();
     }
   }, [currentUser]);

   async function loadBackups() {
     if (currentUser?.role !== "developer" && currentUser?.role !== "operator") {
       return;
     }

     try {
       setBackupLoading(true);
       setBackupError(null);
       const files = await fetchBackups();
       setBackups(files);
     } catch (err: any) {
       setBackupError(err.message || "Backups konnten nicht geladen werden");
     } finally {
       setBackupLoading(false);
     }
   }

   async function handleCreateBackup() {
