            <div style={statsOverviewLabelStyle}> Gesperrt</div>
            <div style={statsOverviewValueStyle}>{statusCounts.blocked}</div>
          </div>
        </section>

        {loading && !hasLoadedOnce && (
            <div style={loadingCardStyle}>Lade Daten...</div>
        )}

        {error && <div style={errorBoxStyle}>{error}</div>}

        {!error && hasLoadedOnce && (
            <div
              style={{
                ...dashboardGridStyle,
                gridTemplateColumns: "minmax(0, 1fr)",
              }}
            >
               <main style={mainColumnStyle}>
                 <section style={matrixCardStyle}>
                   <div style={cardHeaderStyle}>
                     <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start", gap: "1rem", flexWrap: "wrap" }}>
                       <div>
                         <h2 style={cardTitleStyle}>
                           {viewMode === "map" ? "Campingplatzkarte" : "Belegungsmatrix"}
                         </h2>
                         <p style={cardSubtitleStyle}>
                           {viewMode === "map"
                              ? "Wähle einen Platz direkt über die Karte."
                             : "Zeitliche Übersicht der Platzauslastung und Buchungen."}
                         </p>
                       </div>
                       <div style={viewToggleStyle}>
                         <button
                           onClick={() => setViewMode("map")}
                           style={{
                             ...viewToggleButtonStyle,
                             ...(viewMode === "map" ? activeViewToggleButtonStyle : {}),
                           }}
                         >
                           ️ Karte
                         </button>
                         <button
                           onClick={() => setViewMode("matrix")}
                           style={{
                             ...viewToggleButtonStyle,
                             ...(viewMode === "matrix" ? activeViewToggleButtonStyle : {}),
                           }}
                         >
                            Belegungsmatrix
                         </button>
                       </div>
                     </div>
                   </div>

                   {viewMode === "map" ? (
                     <CampingMap
                       places={places}
                       placeStatuses={placeStatuses}
                       bookings={bookings}
                       selectedPlaceId={selectedPlaceId}
                       onSelectPlace={handleSelectPlace}
                       isDeveloper={currentUser.role === "developer"}
                       availablePlaceIds={availablePlaceIds}
                       availabilityMode={availabilityMode}
                     />
                   ) : (
                     <OccupancyMatrix
                       places={places}
                       bookings={bookings}
                       placeStatuses={placeStatuses}
                       selectedPlaceId={selectedPlaceId}
                       onSelectPlace={handleSelectPlace}
                       onSelectDateRange={handleSelectDateRangeFromMatrix}
                       isDeveloper={currentUser.role === "developer"}
                       availablePlaceIds={availablePlaceIds}
                       availabilityMode={availabilityMode}
                     />
                   )}
                 </section>

                <BookingOverview
                  bookings={bookings}
                  places={places}
                  onBookingUpdated={reloadData}
                />
              </main>
            </div>
        )}

        {bookingModalOpen && selectedPlace && (
          <div
            style={bookingModalOverlayStyle}
            onMouseDown={(e) => {
              if (e.target === e.currentTarget) {
                setBookingModalOpen(false);
                setSelectedPlaceId(null);
                setSelectedFocusDateIso(null);
                setSelectedFocusBookingId(null);
              }
            }}
          >
            <div style={bookingModalCardStyle}>
              <div style={bookingModalHeaderStyle}>
                <div>
                  <h2 style={bookingModalTitleStyle}>
                    Neue Buchung – Platz {selectedPlace.name}
                  </h2>

                  <p style={cardSubtitleStyle}>
                    Gastdaten und Buchungszeitraum direkt erfassen.
                  </p>
                </div>

                <button
                    type="button"
                    onClick={() => {
                      setBookingModalOpen(false);
                      setSelectedPlaceId(null);
                      setSelectedFocusDateIso(null);
                      setSelectedFocusBookingId(null);
                    }}
                    style={bookingModalCloseStyle}
                    aria-label="Fenster schließen"
                >
                  ✕
                </button>
              </div>

              <div style={modalTabRowStyle}>
                <button
                    type="button"
                    onClick={() => {
                      setPlaceModalTab("booking");
                      setSelectedFocusDateIso(null);
                      setSelectedFocusBookingId(null);
                    }}
                    style={{
                      ...modalTabButtonStyle,
                      ...(placeModalTab === "booking"
                          ? activeModalTabButtonStyle
                          : {}),
                    }}
                >
                  ➕ Neue Buchung
                </button>

                <button
                    type="button"
                    onClick={() => setPlaceModalTab("details")}
                    style={{
                      ...modalTabButtonStyle,
                      ...(placeModalTab === "details"
                          ? activeModalTabButtonStyle
                          : {}),
                    }}
                >
                   Platzdetails & Buchungen
                </button>
              </div>

              {placeModalTab === "booking" ? (
                <NewBooking
                  place={selectedPlace}
                  bookings={bookingsForSelectedPlace}
                  initialStartDate={searchStartDate}
                  initialEndDate={searchEndDate}
                  initialVehicleLengthM={vehicleLengthM}
                  onBookingCreated={reloadData}
                  onBookingFinished={() => {
                    setBookingModalOpen(false);
                    setSelectedPlaceId(null);
                    setSelectedFocusDateIso(null);
                    setSelectedFocusBookingId(null);
                  }}
                />
              ) : (
                <PlaceDetailPanel
                  place={selectedPlace}
                  bookings={bookingsForSelectedPlace}
                  onBookingCreated={reloadData}
                  canEditPlaces={
                    currentUser.role === "developer" ||
                    currentUser.role === "operator"
                  }
                  showBookingForm={false}
                  initialStartDate={searchStartDate}
                  initialEndDate={searchEndDate}
                  initialVehicleLengthM={vehicleLengthM}
                  focusedDateIso={selectedFocusDateIso}
                  focusedBookingId={selectedFocusBookingId}
                />
              )}
            </div>
          </div>
        )}

        {(currentUser.role === "developer" || currentUser.role === "operator") && (
          <section style={{ ...cardStyle, marginTop: "1rem" }}>
            <div style={cardHeaderStyle}>
              <div>
                <h2 style={cardTitleStyle}>Backups</h2>
                <p style={cardSubtitleStyle}>
                  Datenbanksicherung direkt am Server erstellen und herunterladen.
                </p>
              </div>
            </div>

            <div style={{ display: "flex", gap: "0.75rem", flexWrap: "wrap" }}>
              <button
                onClick={handleCreateBackup}
                disabled={backupActionLoading}
                style={{
                  ...primaryButtonStyle,
                  opacity: backupActionLoading ? 0.65 : 1,
                  cursor: backupActionLoading ? "not-allowed" : "pointer",
                }}
              >
                {backupActionLoading ? "Backup wird erstellt ..." : "Jetzt Backup erstellen"}
              </button>
              <button onClick={loadBackups} style={secondaryButtonStyle}>
                Liste aktualisieren
              </button>
            </div>

            {backupLoading && <div style={{ marginTop: "1rem", color: colors.muted }}>Backups werden geladen ...</div>}
            {backupError && <div style={errorBoxStyle}>{backupError}</div>}
            {backupSuccess && <div style={successBoxStyle}>{backupSuccess}</div>}

            <div style={{ marginTop: "1rem", display: "grid", gap: "0.55rem" }}>
              {backups.length === 0 && !backupLoading ? (
                <div style={{ color: colors.muted }}>Noch keine Backup-Dateien vorhanden.</div>
              ) : (
                backups.map((backup) => (
                  <div
                    key={backup.file_name}
                    style={{
                      display: "flex",
                      justifyContent: "space-between",
                      alignItems: "center",
                      gap: "1rem",
                      border: `1px solid ${colors.border}`,
                      borderRadius: "8px",
                      padding: "0.75rem 0.9rem",
                      backgroundColor: "#ffffff",
                    }}
                  >
                    <div>
                      <div style={{ fontWeight: 700 }}>{backup.file_name}</div>
                      <div style={{ color: colors.muted, fontSize: "0.85rem" }}>
                        {new Date(backup.created_at).toLocaleString("de-DE")} · {(backup.size_bytes / (1024 * 1024)).toFixed(2)} MB
                      </div>
                    </div>
                    <div style={{ display: "flex", gap: "0.5rem", flexWrap: "wrap" }}>
                      <button
                        onClick={() => handleDownloadBackup(backup.file_name)}
                        style={secondaryButtonStyle}
                      >
                        Download
                      </button>
                      {currentUser.role === "developer" && (
                        <button
                          onClick={() => handleRestoreBackup(backup.file_name)}
                          disabled={backupActionLoading}
                          style={{
                            ...secondaryButtonStyle,
                            border: "1.5px solid #fca5a5",
                            color: "#991b1b",
                            opacity: backupActionLoading ? 0.65 : 1,
                            cursor: backupActionLoading ? "not-allowed" : "pointer",
                          }}
                        >
                          Wiederherstellen
                        </button>
                      )}
                    </div>
                  </div>
                ))
              )}
            </div>
          </section>
        )}

        {currentUser.role === "developer" && (
            <section style={{...cardStyle, marginTop: "1rem"}}>
              <div style={cardHeaderStyle}>
                <div>
                  <h2 style={cardTitleStyle}>Benutzer anlegen</h2>
                  <p style={cardSubtitleStyle}>
                    Neuen Operator, Developer oder User für die Anwendung anlegen.
                  </p>
                </div>
              </div>

              <div style={formRowStyle}>
                <div style={fieldBlockStyle}>
                  <label style={labelStyle}>Benutzername</label>
              <input
                value={newUsername}
                onChange={(e) => setNewUsername(e.target.value)}
                style={inputStyle}
              />
            </div>

            <div style={fieldBlockStyle}>
              <label style={labelStyle}>Passwort</label>
              <input
                type="password"
                value={newPassword}
                onChange={(e) => setNewPassword(e.target.value)}
                style={inputStyle}
              />
            </div>

            <div style={fieldBlockStyleNarrow}>
              <label style={labelStyle}>Rolle</label>
              <select
                value={newUserRole}
                onChange={(e) => setNewUserRole(e.target.value)}
                style={inputStyle}
              >
                <option value="operator">Operator</option>
                <option value="user">User</option>
                <option value="developer">Developer</option>
              </select>
            </div>

            <div style={actionFieldStyle}>
              <button
                onClick={handleCreateUser}
                disabled={!newUsername.trim() || !newPassword.trim()}
                style={{
                  ...primaryButtonStyle,
                  opacity: !newUsername.trim() || !newPassword.trim() ? 0.6 : 1,
                  cursor:
                    !newUsername.trim() || !newPassword.trim()
                      ? "not-allowed"
                      : "pointer",
                }}
              >
                Benutzer anlegen
              </button>
            </div>
          </div>

          {userCreateSuccess && <div style={successBoxStyle}>{userCreateSuccess}</div>}
          {userCreateError && <div style={errorBoxStyle}>{userCreateError}</div>}

          <div style={{ marginTop: "2rem" }}>
            <div style={cardHeaderStyle}>
              <div>
                <h2 style={cardTitleStyle}>Benutzerübersicht</h2>
                <p style={cardSubtitleStyle}>
                  Alle vorhandenen Benutzerkonten und Rollen.
                </p>
              </div>
            </div>

            {usersError && <div style={errorBoxStyle}>{usersError}</div>}

            <div style={{ display: "grid", gap: "0.6rem", marginBottom: "1.5rem" }}>
              {users.map((user) => (
                <div
                  key={user.id}
                  style={{
                    display: "flex",
                    justifyContent: "space-between",
                    alignItems: "center",
                    gap: "1rem",
                    padding: "0.75rem 0.9rem",
                    borderRadius: "0.75rem",
                    border: `1px solid ${colors.border}`,
                    backgroundColor: "#ffffff",
                  }}
                >
                  <div style={{ display: "flex", alignItems: "center", gap: "1rem" }}>
                    <strong>{user.username}</strong>
                    <span style={userBadgeStyle}>{user.role}</span>

                    <button
                      onClick={() => handleDeleteUser(user.id)}
                      style={{
                        padding: "0.45rem 0.7rem",
                        borderRadius: "0.6rem",
                        border: "1px solid #fecaca",
                        backgroundColor: "#fee2e2",
                        color: "#991b1b",
                        cursor: "pointer",
                        fontWeight: 700,
                      }}
                    >
                      Löschen
                    </button>
                  </div>
                </div>
              ))}
            </div>
          </div>
        </section>
      )}
      </div>
    </div>
  );
}
const colors = {
  // Neutrals
  pageBg: "#f0f4f8",
