export async function createBooking(data: {
  place_id: number;
  start_date: string;
  end_date: string;
  guest_name: string;
  guest_street?: string;
  guest_postal_code?: string;
  guest_city?: string;
  nationality?: string;
  people_count?: number;
  adult_count?: number;
  child_count?: number;
  day_visitor_count?: number;
  has_electricity?: boolean;
  has_waste?: boolean;
  has_rhine_view?: boolean;
  dog_count?: number;
