  tent_tariff_code?: string | null;
  place_price_per_night?: number | null;
  vehicle_size: string;
  tent_count?: number | null;
  notes: string;
}) {
  const token = getAuthToken();

  const res = await fetch(`${API_BASE_URL}/bookings`, {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
